class Solution:
    def twoEggDrop(self, n: int) -> int:
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = min(1 + max(x - 1, dp[i - x]) for x in range(1, i + 1))
        return dp[n]

c.cpp:
class Solution {
public:
    int twoEggDrop(int n) {
        vector<int> dp(n + 1, INT_MAX);
        dp[0] = 0;
        for (int i = 1; i <= n; ++i)
            for (int x = 1; x <= i; ++x)
                dp[i] = min(dp[i], 1 + max(x - 1, dp[i - x]));
        return dp[n];
    }
};

