class Solution {
    public int twoEggDrop(int n) {
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE;
            for (int x = 1; x <= i; x++)
                dp[i] = Math.min(dp[i], 1 + Math.max(x - 1, dp[i - x]));
        }
        return dp[n];
    }
}

